  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_CLEAR(CSR_MIE)
  LI(a1, 8192)
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_CLEAR(CSR_MIP)
  // 5. software clears OF; counting without overflow leaves it clear
  #if __riscv_xlen == 64
  AI_LOAD(a1)
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_CLEAR(RVTEST_CSR_MHPMEVENT)
  #endif
  #if __riscv_xlen == 32
  AI_LOAD(a1)
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_CLEAR(RVTEST_CSR_MHPMEVENTH)
  #endif
  // mhpmevent = count in S | event
  #if __riscv_xlen == 64
  AI_LOAD(a1)  // mhpmevent bits 63:32
  LI(x6, RVMODEL_MHPMEVENT_VAL)
  or a1, a1, x6
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_WRITE(RVTEST_CSR_MHPMEVENT)
  #endif
  #if __riscv_xlen == 32
  LI(a1, RVMODEL_MHPMEVENT_VAL)
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_WRITE(RVTEST_CSR_MHPMEVENT)
  AI_LOAD(a1)  // mhpmeventh
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_WRITE(RVTEST_CSR_MHPMEVENTH)
  #endif
  LA(x9, scof_evw)
  RVMODEL_MHPMEVENT_CODE(x9, x8)
  // stop counting: set every xINH bit (OF and the event are kept)
  #if __riscv_xlen == 64
  AI_LOAD(a1)
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_SET(RVTEST_CSR_MHPMEVENT)
  #endif
  #if __riscv_xlen == 32
  AI_LOAD(a1)
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_SET(RVTEST_CSR_MHPMEVENTH)
  #endif
mhpmevent_of_op_clr_15:
  #if __riscv_xlen == 64
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_READ(RVTEST_CSR_MHPMEVENT)
  srli x6, a0, 63
  #endif
  #if __riscv_xlen == 32
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_READ(RVTEST_CSR_MHPMEVENTH)
  srli x6, a0, 31
  #endif
  AI_CHECK(x6, mhpmevent_of_op_clr_15, mhpmevent_of_op_clr_15_s13)
  LI(x6, 8192)
  csrc sie, x6
  csrc sip, x6
  LI(a1, 8192)
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_CLEAR(CSR_MIE)
  LI(a1, 8192)
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_CLEAR(CSR_MIP)
  #endif

  // teardown: counter frozen, OF=0, event 0, counter 0
  // mhpmevent = all xINH
  #if __riscv_xlen == 64
  AI_LOAD(a1)  // mhpmevent bits 63:32
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_WRITE(RVTEST_CSR_MHPMEVENT)
  #endif
  #if __riscv_xlen == 32
  LI(a1, 0)
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_WRITE(RVTEST_CSR_MHPMEVENT)
  AI_LOAD(a1)  // mhpmeventh
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_WRITE(RVTEST_CSR_MHPMEVENTH)
  #endif
  #if __riscv_xlen == 64
  AI_LOAD(a1)  // 0
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_WRITE(RVTEST_CSR_MHPMCOUNTER)
  #endif
  #if __riscv_xlen == 32
  AI_LOAD(a1)  // 0 (high half)
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_WRITE(RVTEST_CSR_MHPMCOUNTERH)
  AI_LOAD(a1)  // 0 (low half)
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_WRITE(RVTEST_CSR_MHPMCOUNTER)
  #endif
  LI(x6, 8192)
  csrc sie, x6
  csrc sip, x6
  LI(a1, 8192)
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_CLEAR(CSR_MIE)
  LI(a1, 8192)
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_CLEAR(CSR_MIP)

RVTEST_CODE_END

